import{_ as l,o as i,c as a,a5 as t}from"./chunks/framework.Bt0SrEfo.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"agent/简历.md","filePath":"agent/简历.md","lastUpdated":1789141852000}'),r={name:"agent/简历.md"};function o(n,e,s,p,c,m){return i(),a("div",null,[...e[0]||(e[0]=[t('<h2 id="项目经历-简历版" tabindex="-1">项目经历（简历版） <a class="header-anchor" href="#项目经历-简历版" aria-label="Permalink to &quot;项目经历（简历版）&quot;">​</a></h2><h3 id="一、会员生态前端平台-4端-h5-pc-运营后台-crm" tabindex="-1">一、会员生态前端平台（4端：H5 + PC + 运营后台 + CRM） <a class="header-anchor" href="#一、会员生态前端平台-4端-h5-pc-运营后台-crm" aria-label="Permalink to &quot;一、会员生态前端平台（4端：H5 + PC + 运营后台 + CRM）&quot;">​</a></h3><p><strong>项目背景：</strong> 负责东南亚博彩平台的会员端（H5/PC）和商户运营后台的前端架构与核心业务开发。平台日活用户数万，支撑充值、投注、活动参与等核心交易链路。</p><p><strong>技术栈：</strong> Next.js 15 + React 18 + TypeScript + Ant Design / Ant Design Mobile + TanStack Query + Zustand + Tailwind CSS + i18next + Workbox</p><hr><h3 id="_1-member-mobile-h5移动端-member-web-pc端" tabindex="-1">1. member-mobile（H5移动端）/ member-web（PC端） <a class="header-anchor" href="#_1-member-mobile-h5移动端-member-web-pc端" aria-label="Permalink to &quot;1. member-mobile（H5移动端）/ member-web（PC端）&quot;">​</a></h3><p><strong>核心职责：</strong> 主导用户端核心交易流程和公共组件建设。</p><p><strong>业务链路：</strong></p><ul><li>用户全生命周期 — 注册登录（含 hCaptcha 人机验证 + OTP 短信验证码）→ 充值 → 投注 → 提现 → 活动参与 → 转账</li><li>游戏生态 — 对接 Betby 体育接口、SoulExchange 游戏接口，内嵌第三方游戏页面</li><li>App 混合架构 — 与原生 App WebView 深度兼容，H5 页面同时运行于独立浏览器和 App 内嵌环境，共用同一套代码</li></ul><p><strong>组件封装（核心输出）：</strong></p><ul><li>通用表单控件 — 输入框、下拉选择、图片上传（含裁剪压缩）、富文本编辑器</li><li>交互组件 — 验证码按钮（含倒计时 + 防抖）、按钮 Loading 状态、弹框提示（Toast/Dialog）</li><li>业务组件 — 点击跳转链接、SafeHTML 安全渲染、多语言文案组件</li><li>国际化 — 基于 i18next 实现多语言切换，支持动态语言包加载</li></ul><p><strong>性能与体验：</strong></p><ul><li>骨架屏 + 懒加载策略，首屏渲染 &lt; 2s</li><li>CDN 降级容灾，图片资源自动回源</li><li>PWA Service Worker 配置，支持离线访问</li></ul><p><strong>技术亮点：</strong></p><ul><li>封装 <code>useMemberRequest</code> 请求 hook，集成自动重试、接口缓存、登录态拦截</li><li><code>useOcrRecognition</code> 实现证件 OCR 自动识别填写，减少用户操作成本</li><li>WebView 桥接层封装，统一处理 App 端 Native 能力和 H5 的差异（如顶部导航栏、分享回调）</li></ul><hr><h3 id="_2-merchant-platform-商户运营后台" tabindex="-1">2. merchant-platform（商户运营后台） <a class="header-anchor" href="#_2-merchant-platform-商户运营后台" aria-label="Permalink to &quot;2. merchant-platform（商户运营后台）&quot;">​</a></h3><p><strong>核心职责：</strong> 负责后台核心业务模块和通用组件体系建设。</p><p><strong>业务模块：</strong></p><ul><li>活动中心 — 活动配置、兑换码生成、抽奖记录查询</li><li>财务系统 — 存款/取款订单、对账统计</li><li>VIP体系 — 等级配置、升降级规则</li><li>渠道管理 — 代理渠道配置、数据统计</li><li>报表中心 — 会员日活、平台日报（ECharts 可视化）</li></ul><p><strong>组件二次封装（核心输出）：</strong></p><ul><li>表单控件 — DefaultInput、DefaultSelect、DefaultInputNumber、RangeDatePicker、PhoneInput、EmailInput 等，统一样式和行为规范</li><li>上传组件 — UploadImage，支持图片预览、压缩、格式校验，封装到所有涉及图片的业务场景</li><li>富文本编辑器 — WangEditor 集成，支持多语言文案配置</li><li>查询表单 — SearchForm 封装，集成折叠/展开、重置、搜索按钮逻辑</li><li>表格组件 — CustomTable，支持列配置、排序、分页、批量操作</li><li>抽屉 &amp; 弹框 — DrawerModal 统一封装，支持表单型抽屉和详情型抽屉两种模式</li><li>消息提示 — 全局 Toast、Confirm、Notification 统一调用</li><li>多语言 — MultiLanguage 组件嵌入表单，支持运营人员实时切换预览不同语言版本</li></ul><p><strong>架构贡献：</strong></p><ul><li>统一组件 API 设计规范，所有二次封装组件对外暴露一致的 Props 接口，降低使用成本</li><li>基于 TanStack Query 构建数据层，统一管理接口状态、Loading、Error，替代分散的 useState</li></ul><hr><h3 id="项目整体贡献" tabindex="-1">项目整体贡献 <a class="header-anchor" href="#项目整体贡献" aria-label="Permalink to &quot;项目整体贡献&quot;">​</a></h3><ul><li>主导前端架构设计，制定组件封装规范，推动 H5/PC/后台三端共享同一套组件设计理念</li><li>通过 swagger-typescript-api 自动生成接口类型定义，保证前后端接口一致性</li><li>接入 husky + lint-staged + TypeScript 类型检查，形成完整的代码质量门禁</li></ul>',27)])])}const g=l(r,[["render",o]]);export{h as __pageData,g as default};
